// Report regressions through the real UI and generated files. No external services.
import {chromium} from 'playwright';
import {spawn,execFileSync} from 'node:child_process';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
const root=path.resolve(import.meta.dirname,'..'),base='http://127.0.0.1:8765';
const out=process.env.QA_OUTPUT||path.join(os.tmpdir(),'quote-semantic-qa');await fs.mkdir(out,{recursive:true});
const python=process.env.TEST_PYTHON||process.env.CODEX_PRIMARY_RUNTIME_PYTHON||'python';
const data=await fs.mkdtemp(path.join(os.tmpdir(),'quote-semantic-data-'));
const service=spawn(python,['-m','uvicorn','backend.app:app','--host','127.0.0.1','--port','8765'],{cwd:root,env:{...process.env,WA_QUOTE_DATA:data},stdio:['ignore','pipe','pipe']});
let logs='',browser,page;const errors=[],steps=[],verified=[];
service.stdout.on('data',b=>logs+=b);service.stderr.on('data',b=>logs+=b);
try{
 for(let i=0;i<100;i++){try{if((await fetch(base+'/api/health')).ok)break;}catch{}await new Promise(r=>setTimeout(r,100));}
 let token;
 const call=async(endpoint,body,method=body?'POST':'GET')=>{const r=await fetch(base+'/api'+endpoint,{method,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();assert(r.ok,JSON.stringify(d));return d;};
 token=(await call('/setup',{shop_name:'Semantic Regression Store',boss_password:'semantic-boss-test',staff_password:'semantic-staff-test'})).token;
 await call('/business/import',{filename:'business_demo.xlsx',content_b64:(await fs.readFile(path.join(root,'samples/business_demo.xlsx'))).toString('base64')});
 browser=await chromium.launch({executablePath:process.env.BROWSER_EXECUTABLE,headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
 page=await browser.newPage({viewport:{width:430,height:1000},acceptDownloads:true});page.on('pageerror',e=>errors.push(e.message));page.on('dialog',d=>d.accept());
 await page.goto(base);await page.locator('#loginUser').selectOption('boss');await page.locator('#loginPassword').fill('semantic-boss-test');await page.locator('#loginForm button').click();await page.locator('#view-home').waitFor({state:'visible'});
 async function parse(text){await page.locator('#newGlobal').click();await page.locator('#customer').fill('Synthetic case '+(verified.length+1));await page.locator('#inquiryText').fill(text);await page.locator('#parse').click();await page.locator('#lineCard').waitFor({state:'visible'});await page.locator('#parse:not([disabled])').waitFor({state:'attached'});}
 async function finish(name){await page.locator('#confirmProducts').click();await page.locator('#quoteReviewCard').waitFor({state:'visible'});await page.locator('#sourceConfirmed').check();await page.locator('#saveSubmit').click();await page.waitForFunction(()=>document.getElementById('quoteStatus').textContent==='待老板批准');await page.locator('#approve').click();await page.waitForFunction(()=>document.getElementById('quoteStatus').textContent==='已批准');const id=(await page.locator('#quoteNumber').textContent()).split(' · ')[0];const q=await call('/quotes/'+id);assert(q.review&&q.pricing.requirement.review_id===q.review.review_id);for(const lang of ['zh','en','ms']){await page.locator('#replyLanguage').selectOption(lang);const reply=await page.locator('#replyText').inputValue();assert(reply.includes(q.total));for(const item of q.items)assert(reply.includes(item.quantity));}
 const download=page.waitForEvent('download');await page.locator('#downloadPDF').click();const file=path.join(out,name+'.pdf');await(await download).saveAs(file);
 const pdfText=execFileSync(python,['-c','import fitz,sys;d=fitz.open(sys.argv[1]);print("\\n".join(p.get_text() for p in d))',file],{encoding:'utf8'});assert(pdfText.includes(q.total));for(const item of q.items)assert(pdfText.includes(item.quantity));
 verified.push({case:name,items:q.items.map(({sku,quantity})=>({sku,quantity})),fulfilment:q.pricing.requirement.fulfilment,area:q.pricing.requirement.area,freight:q.pricing.decision.freight,total:q.total,pdf:'verified',replyLanguages:3});return q;}
 await parse('Need 1,020 bags cement 50kg. Deliver to Shah Alam.');assert.equal(await page.locator('#lines input').inputValue(),'1020');await page.locator('[data-issue-code="stock"]').waitFor({state:'visible'});await page.locator('#confirmProducts').click();assert(!(await page.locator('#quoteReviewCard').isVisible()));assert.equal((await call('/quotes')).length,0);
 await page.locator('#backToInquiry').click();await page.locator('#inquiryText').fill('Need 20 bags cement 50kg. Deliver to Shah Alam.');await page.locator('#parse').click();await page.locator('#parse:not([disabled])').waitFor({state:'attached'});assert.equal(await page.locator('#lines input').inputValue(),'20');const fixed=await finish('corrected-thousand');assert.equal(fixed.items[0].quantity,'20');
 steps.push('1,020 stays 1020 and is blocked by stock; correcting the original inquiry to 20 produces a reviewed PDF and three replies');
 await parse('Need 20 bags cement for plastering and 20 bags nails. Deliver to Shah Alam.');assert.equal(await page.locator('#lines input').count(),2);assert.deepEqual(await page.locator('#lines input').evaluateAll(es=>es.map(e=>e.value)),['20','20']);const basket=await finish('two-products');assert.equal(basket.items.length,2);assert(basket.items.some(i=>i.sku.startsWith('NAIL')));steps.push('Two equal quantities remain two products through approval, PDF and all customer replies');
 await parse('Need 20 bags cement 50kg. Do not pick up; deliver to Shah Alam.');assert.equal(await page.locator('#cpFulfilment').inputValue(),'delivery');assert.equal(await page.locator('#cpArea').inputValue(),'Shah Alam');const delivery=await finish('negated-pickup');assert(Number(delivery.pricing.decision.freight)>0);steps.push('Negated collection retains delivery and nonzero freight in the approved quotation and outputs');
 for(const [name,inquiry,field,value]of [
 ['not-fast-en','Need 20 bags cement for plastering, not fast setting. Deliver to Shah Alam.','sku','CEM-A-FAST-50'],
 ['not-fast-zh','我要20袋水泥用于抹灰，不要速凝，送到莎阿南。','sku','CEM-A-FAST-50'],
 ['not-brand','Need 20 bags cement for plastering. No Brand A please. Deliver to Shah Alam.','brand','Brand A']]){await parse(inquiry);assert((await page.locator('#lines').textContent()).includes('已排除'));const q=await finish(name);assert(q.items.every(i=>i[field]!==value));}
 steps.push('English and Chinese exclusions show their meaning and select valid alternatives through approval and generated files');
 await parse('Need 20 bags cement for plastering.\nPrefer fast setting.\nDeliver to Shah Alam.');assert.equal(await page.locator('#lines input').count(),1);assert.equal(await page.locator('#lines select').first().inputValue(),'CEM-A-FAST-50');steps.push('A separate preference line attaches to its one product without creating a ghost item');
 let arrive,release;const arrived=new Promise(r=>arrive=r),gate=new Promise(r=>release=r);await page.route('**/api/requirements/review',async route=>{arrive();await gate;await route.continue();});await page.locator('#confirmProducts').click();await arrived;await page.locator('#lines input').fill('21');release();await page.waitForFunction(()=>document.getElementById('notice').classList.contains('error'));assert(!(await page.locator('#quoteReviewCard').isVisible()));await page.unroute('**/api/requirements/review');
 await page.locator('#confirmProducts').click();let issue=page.locator('[data-issue-code="quantity_changed"]');await issue.waitFor({state:'visible'});await page.setViewportSize({width:320,height:920});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.screenshot({path:path.join(out,'correction-required-320.png'),fullPage:true});await issue.locator('input').fill('Customer confirmed 21 bags');await page.locator('#applyRequirementCorrections').click();await page.locator('#reviewIssues').waitFor({state:'hidden'});
 await page.locator('#lines input').fill('22');await page.locator('#confirmProducts').click();await issue.waitFor({state:'visible'});assert.equal(await issue.locator('input').inputValue(),'');await issue.locator('input').fill('Customer confirmed 22 bags');await page.locator('#uiLang').selectOption('ms');assert.equal(await issue.locator('input').inputValue(),'Customer confirmed 22 bags');await page.locator('#uiLang').selectOption('zh');await page.locator('#applyRequirementCorrections').click();await page.locator('#reviewIssues').waitFor({state:'hidden'});const manual=await finish('manual-correction');assert.equal(manual.items[0].quantity,'22');assert(manual.review.resolutions.some(r=>r.resolution.reason==='Customer confirmed 22 bags'));assert((await page.locator('#reviewAuditLog').textContent()).includes('22 bags'));steps.push('A delayed response cannot advance changed inputs; changing 21 to 22 requires a fresh reason, preserved across languages and recorded on approval');
 await page.setViewportSize({width:320,height:900});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await page.screenshot({path:path.join(out,'reviewed-320.png'),fullPage:true});assert.deepEqual(errors,[]);
 const report={passed:true,browser:browser.version(),steps,verified,errors,externalAPIs:'not called',realWhatsAppAccount:false};await fs.writeFile(path.join(out,'semantic-report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));
}catch(error){if(page)await page.screenshot({path:path.join(out,'failure.png'),fullPage:true}).catch(()=>{});console.error(logs.slice(-1500));throw error;}
finally{if(browser)await browser.close();service.kill('SIGTERM');}
